  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: #0A1628;
      --secondary: #1E3A5F;
      --accent: #C9A962;
      --accent-hover: #D4B872;
      --white: #FFFFFF;
      --light: #F5F7FA;
      --text: #1A1A1A;
      --muted: #6B7280;
      --border: #E5E7EB;
      --font-body: 'Plus Jakarta Sans', sans-serif;
      --font-heading: 'Playfair Display', serif;
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-body);
      font-size: 16px;
      line-height: 1.6;
      color: var(--text);
      background: var(--white);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    img {
      max-width: 100%;
      height: auto;
    }

    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: var(--primary);
      transition: background 0.3s;
    }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 24px;
      max-width: 1440px;
      margin: 0 auto;
      height: 72px;
    }

    .logo {
      font-family: var(--font-heading);
      font-size: 24px;
      font-weight: 600;
      color: var(--white);
      letter-spacing: -0.5px;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 12px 16px;
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
      transition: color 0.2s;
    }

    .nav-link:hover {
      color: var(--accent);
    }

    .nav-link svg {
      width: 12px;
      height: 12px;
      transition: transform 0.2s;
    }

    .nav-item:hover .nav-link svg {
      transform: rotate(180deg);
    }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border-radius: 8px;
      box-shadow: 0 20px 60px rgba(0,0,0,0.15);
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s, visibility 0.3s;
      min-width: 640px;
      padding: 32px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .nav-item:hover .mega-menu {
      opacity: 1;
      visibility: visible;
    }

    .mega-menu-section h3 {
      font-family: var(--font-body);
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--muted);
      margin-bottom: 16px;
    }

    .mega-menu-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .mega-menu-list a {
      font-size: 14px;
      font-weight: 500;
      color: var(--text);
      transition: color 0.2s;
      display: block;
      padding: 4px 0;
    }

    .mega-menu-list a:hover {
      color: var(--accent);
    }

    /* Mobile Nav Toggle */
    .nav-toggle {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    .nav-toggle svg {
      width: 24px;
      height: 24px;
      color: var(--white);
    }

    /* Mobile Navigation */
    .nav-mobile {
      display: none;
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      background: var(--primary);
      max-height: calc(100vh - 72px);
      overflow-y: auto;
    }

    .nav-mobile.active {
      display: block;
    }

    .mobile-nav-section {
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }

    .mobile-nav-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 16px 24px;
      cursor: pointer;
      color: var(--white);
      font-weight: 500;
      font-size: 14px;
    }

    .mobile-nav-header svg {
      width: 16px;
      height: 16px;
      transition: transform 0.2s;
    }

    .mobile-nav-header.active svg {
      transform: rotate(180deg);
    }

    .mobile-nav-content {
      display: none;
      padding: 0 24px 16px;
    }

    .mobile-nav-content.active {
      display: block;
    }

    .mobile-nav-content a {
      display: block;
      padding: 10px 0;
      color: rgba(255,255,255,0.8);
      font-size: 14px;
    }

    .mobile-nav-content a:hover {
      color: var(--accent);
    }

    /* Hero Section */
    .hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
      padding-top: 72px;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 800"><rect fill="%230A1628" width="1200" height="800"/><g fill="%23ffffff" fill-opacity="0.03"><rect x="100" y="100" width="80" height="300"/><rect x="250" y="150" width="60" height="250"/><rect x="400" y="80" width="100" height="350"/><rect x="600" y="120" width="70" height="280"/><rect x="750" y="90" width="90" height="320"/><rect x="900" y="140" width="60" height="260"/><rect x="1050" y="100" width="80" height="300"/></g></svg>') center/cover;
      opacity: 0.5;
    }

    .hero-content {
      position: relative;
      z-index: 1;
      max-width: 800px;
      padding: 80px 24px;
    }

    .hero-badge {
      display: inline-block;
      background: var(--accent);
      color: var(--primary);
      font-size: 12px;
      font-weight: 600;
      padding: 6px 12px;
      border-radius: 4px;
      margin-bottom: 24px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }

    .hero h1 {
      font-family: var(--font-heading);
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 600;
      color: var(--white);
      line-height: 1.15;
      margin-bottom: 24px;
      letter-spacing: -1px;
    }

    .hero p {
      font-size: 18px;
      color: rgba(255,255,255,0.85);
      margin-bottom: 32px;
      max-width: 600px;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 28px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 6px;
      transition: all 0.2s;
      cursor: pointer;
      border: none;
    }

    .btn-primary {
      background: var(--accent);
      color: var(--primary);
    }

    .btn-primary:hover {
      background: var(--accent-hover);
      transform: translateY(-2px);
    }

    .btn-secondary {
      background: transparent;
      color: var(--white);
      border: 1px solid rgba(255,255,255,0.3);
    }

    .btn-secondary:hover {
      background: rgba(255,255,255,0.1);
    }

    /* Featured Insights */
    .section {
      padding: 80px 0;
    }

    .section-dark {
      background: var(--primary);
      color: var(--white);
    }

    .section-light {
      background: var(--light);
    }

    .section-header {
      margin-bottom: 48px;
    }

    .section-label {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--accent);
      margin-bottom: 12px;
    }

    .section-title {
      font-family: var(--font-heading);
      font-size: clamp(28px, 3vw, 40px);
      font-weight: 600;
      line-height: 1.2;
      letter-spacing: -0.5px;
    }

    .section-title-light {
      color: var(--white);
    }

    /* Announcement Banner */
    .announcement {
      background: var(--secondary);
      padding: 16px 0;
    }

    .announcement-inner {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .announcement-text {
      color: var(--white);
      font-size: 14px;
      font-weight: 500;
    }

    .announcement .btn {
      padding: 8px 16px;
      font-size: 12px;
    }

    /* About Statement */
    .about-statement {
      padding: 120px 0;
    }

    .about-content {
      max-width: 900px;
      margin: 0 auto;
      text-align: center;
    }

    .about-content p {
      font-size: 20px;
      line-height: 1.7;
      color: var(--text);
      margin-bottom: 32px;
    }

    .about-link {
      color: var(--secondary);
      font-weight: 600;
      display: inline-flex;
      align-items: center;
      gap: 6px;
      transition: color 0.2s;
    }

    .about-link:hover {
      color: var(--accent);
    }

    /* What We Do Tabs */
    .what-we-do {
      padding: 100px 0;
    }

    .tabs-container {
      display: grid;
      grid-template-columns: 280px 1fr;
      gap: 48px;
    }

    .tabs-list {
      list-style: none;
      border-right: 1px solid var(--border);
    }

    .tab-item {
      padding: 20px 24px;
      cursor: pointer;
      border-right: 3px solid transparent;
      transition: all 0.2s;
    }

    .tab-item:hover {
      background: var(--light);
    }

    .tab-item.active {
      border-right-color: var(--accent);
      background: var(--light);
    }

    .tab-item h3 {
      font-size: 16px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 4px;
    }

    .tab-item p {
      font-size: 13px;
      color: var(--muted);
    }

    .tab-content {
      display: none;
    }

    .tab-content.active {
      display: block;
    }

    .tab-content h2 {
      font-family: var(--font-heading);
      font-size: 32px;
      font-weight: 600;
      margin-bottom: 16px;
    }

    .tab-content p {
      font-size: 16px;
      color: var(--muted);
      margin-bottom: 24px;
      max-width: 600px;
    }

    /* Newsletter Section */
    .newsletter {
      background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
      padding: 80px 0;
      text-align: center;
    }

    .newsletter h2 {
      font-family: var(--font-heading);
      font-size: 36px;
      color: var(--white);
      margin-bottom: 12px;
    }

    .newsletter p {
      color: rgba(255,255,255,0.8);
      margin-bottom: 32px;
      font-size: 16px;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto;
    }

    .newsletter-input {
      flex: 1;
      padding: 14px 20px;
      border: none;
      border-radius: 6px;
      font-size: 14px;
      background: var(--white);
    }

    .newsletter-input::placeholder {
      color: var(--muted);
    }

    /* Latest Insights Grid */
    .insights-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
    }

    .insight-card {
      background: var(--white);
      border-radius: 8px;
      overflow: hidden;
      box-shadow: 0 4px 20px rgba(0,0,0,0.08);
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .insight-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.12);
    }

    .insight-image {
      height: 180px;
      background: linear-gradient(135deg, var(--secondary) 0%, var(--primary) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .insight-image svg {
      width: 48px;
      height: 48px;
      color: rgba(255,255,255,0.3);
    }

    .insight-content {
      padding: 24px;
    }

    .insight-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--accent);
      background: rgba(201,169,98,0.1);
      padding: 4px 10px;
      border-radius: 4px;
      margin-bottom: 12px;
    }

    .insight-content h3 {
      font-size: 18px;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 8px;
      color: var(--text);
    }

    .insight-content p {
      font-size: 13px;
      color: var(--muted);
    }

    /* Commitment Pillars */
    .commitment-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 32px;
    }

    .commitment-card {
      padding: 32px;
      background: var(--secondary);
      border-radius: 8px;
      transition: transform 0.3s;
    }

    .commitment-card:hover {
      transform: translateY(-4px);
    }

    .commitment-icon {
      width: 48px;
      height: 48px;
      background: var(--accent);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .commitment-icon svg {
      width: 24px;
      height: 24px;
      color: var(--primary);
    }

    .commitment-card h3 {
      font-size: 18px;
      font-weight: 600;
      color: var(--white);
      margin-bottom: 12px;
    }

    .commitment-card p {
      font-size: 14px;
      color: rgba(255,255,255,0.75);
      margin-bottom: 20px;
      line-height: 1.6;
    }

    .commitment-link {
      font-size: 13px;
      font-weight: 600;
      color: var(--accent);
      display: inline-flex;
      align-items: center;
      gap: 4px;
    }

    .commitment-link:hover {
      text-decoration: underline;
    }

    /* Footer */
    .footer {
      background: var(--primary);
      color: var(--white);
      padding: 60px 0 30px;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(4, 1fr);
      gap: 48px;
      margin-bottom: 48px;
    }

    .footer-brand p {
      font-size: 14px;
      color: rgba(255,255,255,0.7);
      margin-top: 16px;
      max-width: 280px;
      line-height: 1.6;
    }

    .footer-column h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1px;
      margin-bottom: 20px;
      color: rgba(255,255,255,0.5);
    }

    .footer-column ul {
      list-style: none;
    }

    .footer-column li {
      margin-bottom: 12px;
    }

    .footer-column a {
      font-size: 14px;
      color: rgba(255,255,255,0.8);
      transition: color 0.2s;
    }

    .footer-column a:hover {
      color: var(--accent);
    }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 30px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 16px;
    }

    .footer-legal {
      display: flex;
      gap: 24px;
    }

    .footer-legal a {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
    }

    .footer-legal a:hover {
      color: var(--white);
    }

    /* Featured Insights Bar */
    .featured-insights {
      padding: 60px 0;
      background: var(--light);
    }

    .featured-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .featured-card {
      display: flex;
      gap: 16px;
      padding: 24px;
      background: var(--white);
      border-radius: 8px;
      box-shadow: 0 2px 12px rgba(0,0,0,0.06);
      transition: box-shadow 0.3s;
    }

    .featured-card:hover {
      box-shadow: 0 8px 24px rgba(0,0,0,0.1);
    }

    .featured-icon {
      width: 48px;
      height: 48px;
      background: var(--secondary);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .featured-icon svg {
      width: 24px;
      height: 24px;
      color: var(--white);
    }

    .featured-content h3 {
      font-size: 14px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 4px;
    }

    .featured-content p {
      font-size: 13px;
      color: var(--muted);
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .nav-desktop {
        display: none;
      }

      .nav-toggle {
        display: block;
      }

      .tabs-container {
        grid-template-columns: 1fr;
      }

      .tabs-list {
        border-right: none;
        border-bottom: 1px solid var(--border);
        display: flex;
        overflow-x: auto;
        gap: 0;
      }

      .tab-item {
        border-right: none;
        border-bottom: 3px solid transparent;
        padding: 16px 20px;
        white-space: nowrap;
      }

      .tab-item.active {
        border-right-color: transparent;
        border-bottom-color: var(--accent);
      }

      .insights-grid,
      .commitment-grid,
      .featured-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .newsletter-form {
        flex-direction: column;
      }
    }

    @media (max-width: 768px) {
      .section {
        padding: 60px 0;
      }

      .hero-content {
        padding: 60px 24px;
      }

      .insights-grid,
      .commitment-grid,
      .featured-grid {
        grid-template-columns: 1fr;
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }

      .footer-legal {
        flex-wrap: wrap;
        justify-content: center;
      }
    }

    /* Animation */
    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .animate-in {
      animation: fadeInUp 0.6s ease-out forwards;
    }

    .delay-1 { animation-delay: 0.1s; }
    .delay-2 { animation-delay: 0.2s; }
    .delay-3 { animation-delay: 0.3s; }
    .delay-4 { animation-delay: 0.4s; }
  </style>
</head>
