      .topics-layout {
        grid-template-columns: 1fr;
      }

      .topics-sidebar {
        max-width: 400px;
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .page-hero {
        min-height: 45vh;
      }

      .capabilities-grid,
      .related-grid,
      .insights-grid {
        grid-template-columns: 1fr;
      }

      .property-types-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .partner-card {
        flex: 0 0 100%;
